using Microsoft.Build.Logging.StructuredLogger;
using STask = Microsoft.Build.Logging.StructuredLogger.Task;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

// Get all errors with full project context  
var errors = new List<(string project, string file, int line, int col, string code, string message)>();

void Visit(BaseNode node, string currentProject = "")
{
    if (node is Project p) currentProject = p.Name;
    if (node is Microsoft.Build.Logging.StructuredLogger.Error e)
        errors.Add((currentProject, e.File ?? "", e.LineNumber, e.ColumnNumber, e.Code ?? "", e.Text ?? ""));
    if (node is TreeNode tn)
        foreach (var child in tn.Children)
            if (child is BaseNode bn)
                Visit(bn, currentProject);
}
Visit(build);

// Check project build results
void VisitProjects(BaseNode node) 
{
    if (node is Project p)
        Console.WriteLine($"Project: {p.Name} | Succeeded: {p.Succeeded}");
    if (node is TreeNode tn)
        foreach (var child in tn.Children)
            if (child is BaseNode bn)
                VisitProjects(bn);
}

Console.WriteLine("=== PROJECT BUILD RESULTS ===");
VisitProjects(build);

Console.WriteLine("\n=== ALL ERRORS ===");
foreach (var e in errors)
    Console.WriteLine($"[{e.project}] {e.file}({e.line},{e.col}): error {e.code}: {e.message}");

// Also look for "project failed" messages
void FindMessages(BaseNode node, string currentProject = "")
{
    if (node is Project p) currentProject = p.Name;
    if (node is Message m && m.Text != null && (m.Text.Contains("failed") || m.Text.Contains("error")))
        Console.WriteLine($"[{currentProject}] MSG: {m.Text}");
    if (node is TreeNode tn)
        foreach (var child in tn.Children)
            if (child is BaseNode bn)
                FindMessages(bn, currentProject);
}

Console.WriteLine("\n=== FAILURE-RELATED MESSAGES ===");
FindMessages(build);

// Get embedded file contents
Console.WriteLine("\n=== EMBEDDED FILES (SourceFiles) ===");
void FindFiles(BaseNode node, string prefix = "")
{
    if (node is SourceFile sf)
        Console.WriteLine($"{prefix}SourceFile: {sf.Name}");
    if (node is TreeNode tn)
        foreach (var child in tn.Children)
            if (child is BaseNode bn)
                FindFiles(bn, prefix + "  ");
}
FindFiles(build);
